import { createHash } from "node:crypto";
import { cp, mkdir, mkdtemp, readFile, rm, stat, utimes, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	type ArtifactCache,
	createArtifactCache,
	type DerivedArtifact,
} from "../artifact-cache.js";

vi.unmock("node:fs");
vi.unmock("node:fs/promises");
vi.unmock("fs");
vi.unmock("fs/promises");

describe("shared artifact cache (real SQLite and files)", () => {
	let directory: string;
	let databasePath: string;
	let published: string;
	let staged: string;
	let input: string;
	const instances: ArtifactCache[] = [];

	beforeEach(async () => {
		directory = await mkdtemp(path.join(os.tmpdir(), "launchpad-artifacts-"));
		databasePath = path.join(directory, ".launchpad/cache/artifacts.sqlite");
		published = path.join(directory, "published");
		staged = path.join(directory, "staged");
		input = path.join(directory, "input.txt");
		await writeFile(input, "source bytes");
	});

	afterEach(async () => {
		for (const cache of instances.splice(0)) await cache.close();
		await rm(directory, { recursive: true, force: true });
	});

	async function openCache(overrides: Partial<Parameters<typeof createArtifactCache>[0]> = {}) {
		const cache = await createArtifactCache({
			databasePath,
			previousRoot: (sourceId) => path.join(published, sourceId),
			stagedRoot: (sourceId) => path.join(staged, sourceId),
			...overrides,
		});
		instances.push(cache);
		return cache;
	}

	function artifact(overrides: Partial<DerivedArtifact> = {}): DerivedArtifact {
		return {
			sourceId: "source",
			namespace: "test-transform",
			version: "1",
			inputs: [input],
			options: { width: 100, height: 200 },
			outputs: ["nested/result.txt"],
			generate: async () => {
				await mkdir(path.join(staged, "source/nested"), { recursive: true });
				await writeFile(path.join(staged, "source/nested/result.txt"), "generated bytes");
			},
			...overrides,
		};
	}

	async function publish(cache: ArtifactCache, sources = ["source"]) {
		await cache.beginPublication(sources);
		await cp(staged, published, { recursive: true });
		await cache.commitPublication((sourceId) => path.join(published, sourceId));
	}

	async function seed() {
		const cache = await openCache();
		expect(await cache.derive(artifact())).toEqual({ reused: false });
		await publish(cache);
	}

	it("records actual outputs only after publication and restores unchanged filenames", async () => {
		const cache = await openCache();
		await cache.derive(artifact());
		const database = new DatabaseSync(databasePath);
		expect(database.prepare("SELECT * FROM artifacts").all()).toHaveLength(0);
		await publish(cache);
		const rows = database.prepare("SELECT record_json FROM artifacts").all();
		expect(rows).toHaveLength(1);
		expect(String(rows[0]?.record_json)).toContain(
			createHash("sha256").update("generated bytes").digest("hex"),
		);
		database.close();
		await rm(staged, { recursive: true });
		const next = await openCache();
		const generate = vi.fn();
		expect(await next.derive(artifact({ generate }))).toEqual({ reused: true });
		expect(generate).not.toHaveBeenCalled();
		expect(await readFile(path.join(staged, "source/nested/result.txt"), "utf8")).toBe(
			"generated bytes",
		);
	});

	it("identifies inputs by content rather than copy timestamps and canonicalizes options", async () => {
		await seed();
		await utimes(input, new Date(1000), new Date(1000));
		const next = await openCache();
		expect(await next.derive(artifact({ options: { height: 200, width: 100 } }))).toEqual({
			reused: true,
		});
	});

	it.each(["input", "options", "version", "namespace"])(
		"misses when %s changes",
		async (change) => {
			await seed();
			const request = artifact();
			if (change === "input") await writeFile(input, "new source content");
			if (change === "options") request.options = { width: 300 };
			if (change === "version") request.version = "2";
			if (change === "namespace") request.namespace = "different-transform";
			const next = await openCache();
			expect(await next.derive(request)).toEqual({ reused: false });
		},
	);

	it("rehashes a previous output with changed attributes and refreshes final attributes", async () => {
		await seed();
		const file = path.join(published, "source/nested/result.txt");
		await utimes(file, new Date(2000), new Date(2000));
		const next = await openCache();
		expect(await next.derive(artifact())).toEqual({ reused: true });
		await publish(next);
		const database = new DatabaseSync(databasePath);
		expect(
			String(database.prepare("SELECT record_json FROM artifacts").get()?.record_json),
		).toContain(String((await stat(file)).mtimeMs));
		database.close();
	});

	it.each(["changed", "missing", "no-publication"])(
		"misses for %s previous output",
		async (condition) => {
			await seed();
			const file = path.join(published, "source/nested/result.txt");
			if (condition === "changed") await writeFile(file, "edited output");
			if (condition === "missing") await rm(file);
			const cache = await openCache(
				condition === "no-publication" ? { previousRoot: () => undefined } : {},
			);
			expect(await cache.derive(artifact())).toEqual({ reused: false });
		},
	);

	it("coalesces identical concurrent generation and rejects different identities at a destination", async () => {
		const cache = await openCache();
		const generate = vi.fn(artifact().generate);
		const results = await Promise.all([
			cache.derive(artifact({ generate })),
			cache.derive(artifact({ generate })),
		]);
		expect(results).toEqual([{ reused: false }, { reused: false }]);
		expect(generate).toHaveBeenCalledTimes(1);
		await expect(cache.derive(artifact({ version: "2" }))).rejects.toMatchObject({
			code: "output-conflict",
		});
	});

	it.each(["unchanged", "missing", "changed"])(
		"revalidates completed generated output when it is %s",
		async (condition) => {
			const cache = await openCache();
			const generate = vi.fn(artifact().generate);
			const request = artifact({ generate });
			expect(await cache.derive(request)).toEqual({ reused: false });
			const output = path.join(staged, "source/nested/result.txt");
			if (condition === "missing") await rm(output);
			if (condition === "changed") {
				const attributes = await stat(output);
				await writeFile(output, "corrupted bytes");
				await utimes(output, attributes.atime, attributes.mtime);
			}
			expect(await cache.derive(request)).toEqual({ reused: condition === "unchanged" });
			expect(generate).toHaveBeenCalledTimes(condition === "unchanged" ? 1 : 2);
			expect(await readFile(output, "utf8")).toBe("generated bytes");
			await publish(cache);
			const next = await openCache();
			expect(await next.derive(request)).toEqual({ reused: true });
		},
	);

	it.each(["missing", "changed"])(
		"restores a completed publication hit again after its staged output is %s",
		async (condition) => {
			await seed();
			const cache = await openCache();
			const generate = vi.fn();
			const request = artifact({ generate });
			expect(await cache.derive(request)).toEqual({ reused: true });
			const output = path.join(staged, "source/nested/result.txt");
			if (condition === "missing") await rm(output);
			else await writeFile(output, "downstream mutation");
			expect(await cache.derive(request)).toEqual({ reused: true });
			expect(generate).not.toHaveBeenCalled();
			expect(await readFile(output, "utf8")).toBe("generated bytes");
		},
	);

	it("revalidates every output of a completed multi-output artifact", async () => {
		const cache = await openCache();
		const generate = vi.fn(async () => {
			await mkdir(path.join(staged, "source"), { recursive: true });
			await writeFile(path.join(staged, "source/one"), "first");
			await writeFile(path.join(staged, "source/two"), "second");
		});
		const request = artifact({ outputs: ["one", "two"], generate });
		await cache.derive(request);
		await rm(path.join(staged, "source/two"));
		expect(await cache.derive(request)).toEqual({ reused: false });
		expect(generate).toHaveBeenCalledTimes(2);
		expect(await readFile(path.join(staged, "source/two"), "utf8")).toBe("second");
	});

	it("claims resolved destinations across source ids and HTTP/derived kinds", async () => {
		const cache = await openCache({ stagedRoot: () => staged });
		await mkdir(staged, { recursive: true });
		await writeFile(path.join(staged, "same"), "http");
		await cache.storeHttp({ sourceId: "one", key: "url", outputPath: "same", metadata: null });
		await expect(
			cache.storeHttp({ sourceId: "two", key: "url", outputPath: "./same", metadata: null }),
		).rejects.toMatchObject({ code: "output-conflict" });
		await expect(
			cache.derive(artifact({ sourceId: "one", outputs: ["same"] })),
		).rejects.toMatchObject({ code: "output-conflict" });
	});

	it("does not durably cache in-place transforms", async () => {
		const cache = await openCache();
		await mkdir(path.join(staged, "source"), { recursive: true });
		const file = path.join(staged, "source/in-place");
		await writeFile(file, "before");
		const generate = vi.fn(async () => {
			await writeFile(file, "after");
		});
		expect(
			await cache.derive(artifact({ inputs: [file], outputs: ["in-place"], generate })),
		).toEqual({ reused: false });
		await publish(cache);
		const database = new DatabaseSync(databasePath);
		expect(database.prepare("SELECT * FROM artifacts").all()).toHaveLength(0);
		database.close();
	});

	it("drops generated entries mutated downstream even if attributes are restored", async () => {
		await seed();
		const cache = await openCache();
		expect(await cache.derive(artifact())).toEqual({ reused: true });
		const file = path.join(staged, "source/nested/result.txt");
		const attributes = await stat(file);
		await writeFile(file, "transformed out");
		await utimes(file, attributes.atime, attributes.mtime);
		await publish(cache);
		const database = new DatabaseSync(databasePath);
		expect(database.prepare("SELECT * FROM artifacts").all()).toHaveLength(0);
		database.close();
		const next = await openCache();
		expect(await next.derive(artifact())).toEqual({ reused: false });
	});

	it("round-trips arbitrary HTTP JSON metadata with explicit source-scoped lookup", async () => {
		const cache = await openCache();
		await mkdir(path.join(staged, "source"), { recursive: true });
		await writeFile(path.join(staged, "source/photo.jpg"), "download bytes");
		const http = { sourceId: "source", key: "https://example.test/photo", outputPath: "photo.jpg" };
		const metadata = {
			policy: { etag: "v1", cacheControl: ["private", 300] },
			flag: true,
			nil: null,
		};
		await cache.storeHttp({ ...http, metadata });
		expect(await cache.lookupRecord("source", http.key, "http")).toBeUndefined();
		await publish(cache);
		const next = await openCache();
		expect((await next.lookupRecord("source", http.key, "http"))?.metadata).toEqual(metadata);
		expect(await next.lookupRecord("other-source", http.key, "http")).toBeUndefined();
		await rm(staged, { recursive: true });
		expect((await next.lookupHttp(http))?.filePath).toBe(path.join(published, "source/photo.jpg"));
		await expect(readFile(path.join(staged, "source/photo.jpg"))).rejects.toThrow();
		expect(await next.reuseHttp(http)).toBe(true);
		expect(await readFile(path.join(staged, "source/photo.jpg"), "utf8")).toBe("download bytes");
		await rm(path.join(published, "source/photo.jpg"));
		expect(await next.lookupHttp(http)).toBeUndefined();
		// Raw policy lookup is deliberately independent of file existence.
		expect((await next.lookupRecord("source", http.key, "http"))?.metadata).toEqual(metadata);
	});

	it("allows uncached in-place downstream work without claiming the upstream destination", async () => {
		const cache = await openCache();
		await mkdir(path.join(staged, "source"), { recursive: true });
		const file = path.join(staged, "source/photo.jpg");
		await writeFile(file, "download bytes");
		await cache.storeHttp({
			sourceId: "source",
			key: "url",
			outputPath: "photo.jpg",
			metadata: null,
		});
		const generate = vi.fn(async () => {
			await writeFile(file, "downstream");
		});
		const request = artifact({ inputs: [file], outputs: ["photo.jpg"], generate });
		expect(await cache.derive(request)).toEqual({ reused: false });
		expect(await cache.derive(request)).toEqual({ reused: false });
		expect(generate).toHaveBeenCalledTimes(2);
		await publish(cache);
		const next = await openCache();
		expect(await next.lookupRecord("source", "url", "http")).toBeUndefined();
	});

	it("does not attach an HTTP record's hash to a downstream transformed original", async () => {
		const cache = await openCache();
		await mkdir(path.join(staged, "source"), { recursive: true });
		const file = path.join(staged, "source/photo.jpg");
		await writeFile(file, "download bytes");
		await cache.storeHttp({
			sourceId: "source",
			key: "url",
			outputPath: "photo.jpg",
			metadata: { etag: "1" },
		});
		await writeFile(file, "sharp modified bytes");
		await publish(cache);
		const next = await openCache();
		expect(await next.lookupRecord("source", "url", "http")).toBeUndefined();
	});

	it.each(["not json", JSON.stringify({ outputs: [] }), JSON.stringify({ sourceId: "wrong" })])(
		"validates untrusted stored JSON (%s)",
		async (json) => {
			await seed();
			const database = new DatabaseSync(databasePath);
			database.prepare("UPDATE artifacts SET record_json = ?").run(json);
			database.close();
			const next = await openCache();
			expect(await next.derive(artifact())).toEqual({ reused: false });
		},
	);

	it("rejects traversal in otherwise valid stored records as a cache miss", async () => {
		await seed();
		const database = new DatabaseSync(databasePath);
		database.exec(
			`UPDATE artifacts SET record_json = json_set(record_json, '$.outputs[0].path', '../outside')`,
		);
		database.close();
		const cache = await openCache();
		expect(await cache.derive(artifact())).toEqual({ reused: false });
	});

	it("supports multiple output files as one artifact and misses when any file is absent", async () => {
		const cache = await openCache();
		const request = artifact({
			outputs: ["one", "two"],
			generate: async () => {
				await mkdir(path.join(staged, "source"), { recursive: true });
				await writeFile(path.join(staged, "source/one"), "first output");
				await writeFile(path.join(staged, "source/two"), "second output");
			},
		});
		await cache.derive(request);
		await publish(cache);
		const next = await openCache();
		expect(await next.derive(request)).toEqual({ reused: true });
		await rm(path.join(published, "source/two"));
		const missing = await openCache();
		expect(await missing.derive(request)).toEqual({ reused: false });
	});

	it("allows an identical retry but fails publication closed after a generation failure", async () => {
		const cache = await openCache();
		await expect(
			cache.derive(
				artifact({
					generate: async () => {
						throw new Error("generation failed");
					},
				}),
			),
		).rejects.toThrow("generation failed");
		expect(await cache.derive(artifact())).toEqual({ reused: false });
		await expect(cache.beginPublication(["source"])).rejects.toMatchObject({ code: "generation" });
	});

	it("leaves unsafe sources unreadable after an aborted publication while preserving other sources", async () => {
		const cache = await openCache();
		await cache.derive(artifact());
		await cache.derive(
			artifact({
				sourceId: "other",
				generate: async () => {
					await mkdir(path.join(staged, "other/nested"), { recursive: true });
					await writeFile(path.join(staged, "other/nested/result.txt"), "other output");
				},
			}),
		);
		await publish(cache, ["source", "other"]);
		const aborted = await openCache();
		await aborted.beginPublication(["source"]);
		await aborted.abort();
		const next = await openCache();
		expect(await next.derive(artifact())).toEqual({ reused: false });
		expect(await next.derive(artifact({ sourceId: "other" }))).toEqual({ reused: true });
		await publish(next, ["source", "other"]);
		const repaired = await openCache();
		expect(await repaired.derive(artifact())).toEqual({ reused: true });
	});

	it("invalidates only the requested source", async () => {
		await seed();
		const cache = await openCache();
		await cache.invalidate(["not-source"]);
		expect(await cache.derive(artifact())).toEqual({ reused: true });
		await cache.invalidate(["source"]);
		const next = await openCache();
		expect(await next.derive(artifact())).toEqual({ reused: false });
	});

	it("runs uncached with a warning for corrupt SQLite, but refuses unsafe publication", async () => {
		await mkdir(path.dirname(databasePath), { recursive: true });
		await writeFile(databasePath, "not a database");
		const warn = vi.fn();
		const cache = await openCache({ warn });
		expect(cache.available).toBe(false);
		expect(warn).toHaveBeenCalledOnce();
		expect(await cache.derive(artifact())).toEqual({ reused: false });
		await expect(cache.beginPublication(["source"])).rejects.toMatchObject({ code: "unavailable" });
		await expect(cache.invalidate(["source"])).rejects.toMatchObject({ code: "unavailable" });
	});

	it.each([
		{ method: "abort", inPlace: false },
		{ method: "close", inPlace: false },
		{ method: "abort", inPlace: true },
		{ method: "close", inPlace: true },
	] as const)(
		"$method drains outstanding generation (inPlace=$inPlace)",
		async ({ method, inPlace }) => {
			const cache = await openCache();
			const started = Promise.withResolvers<void>();
			const release = Promise.withResolvers<void>();
			const target = path.join(staged, "source/nested/result.txt");
			await mkdir(path.dirname(target), { recursive: true });
			await writeFile(target, "before");
			const task = cache.derive(
				artifact({
					inputs: inPlace ? [target] : [input],
					generate: async () => {
						started.resolve();
						await release.promise;
						await writeFile(target, "finished generation");
					},
				}),
			);
			await started.promise;
			let drained = false;
			const cleanup = cache[method]().then(() => {
				drained = true;
			});
			await Promise.resolve();
			expect(drained).toBe(false);
			await expect(cache.derive(artifact())).rejects.toMatchObject({ code: "publication" });
			release.resolve();
			await expect(task).resolves.toEqual({ reused: false });
			await cleanup;
			expect(drained).toBe(true);
			expect(await readFile(target, "utf8")).toBe("finished generation");
			const database = new DatabaseSync(databasePath);
			expect(database.prepare("SELECT * FROM artifacts").all()).toHaveLength(0);
			database.close();
		},
	);

	it("abort drains rejecting generation without replacing the caller's generation error", async () => {
		const cache = await openCache();
		const started = Promise.withResolvers<void>();
		const release = Promise.withResolvers<void>();
		const task = cache.derive(
			artifact({
				generate: async () => {
					started.resolve();
					await release.promise;
					throw new Error("generation failed");
				},
			}),
		);
		const result = expect(task).rejects.toThrow("generation failed");
		await started.promise;
		const cleanup = cache.abort();
		release.resolve();
		await expect(cleanup).resolves.toBeUndefined();
		await result;
	});

	it("requires a successful publication begin before committing metadata", async () => {
		const cache = await openCache();
		await cache.derive(artifact());
		await expect(
			cache.commitPublication((sourceId) => path.join(published, sourceId)),
		).rejects.toMatchObject({ code: "publication" });
		await publish(cache);
	});

	it("claims HTTP destinations before any bytes exist", async () => {
		const cache = await openCache();
		await cache.claimHttp({ sourceId: "source", key: "url-one", outputPath: "photo.jpg" });
		await cache.claimHttp({ sourceId: "source", key: "url-one", outputPath: "./photo.jpg" });
		await expect(
			cache.claimHttp({ sourceId: "source", key: "url-two", outputPath: "photo.jpg" }),
		).rejects.toMatchObject({ code: "output-conflict" });
	});

	it("supports explicitly disabled execution without creating a database", async () => {
		const cache = await openCache({ enabled: false });
		expect(cache.available).toBe(false);
		expect(await cache.derive(artifact())).toEqual({ reused: false });
		await expect(stat(databasePath)).rejects.toThrow();
		await expect(cache.beginPublication(["source"])).rejects.toMatchObject({ code: "unavailable" });
	});

	it("rejects absolute and escaping output paths before generation", async () => {
		const cache = await openCache();
		const generate = vi.fn();
		await expect(cache.derive(artifact({ outputs: ["../escape"], generate }))).rejects.toThrow(
			"escapes",
		);
		await expect(cache.derive(artifact({ outputs: [input], generate }))).rejects.toThrow("Invalid");
		expect(generate).not.toHaveBeenCalled();
	});
});
